"""Refund quantities and amounts. Only ISSUED records count."""

import hashlib
from collections.abc import Sequence

from support_agent.domain.ids import CustomerId, IdempotencyKey, ItemId, OrderId
from support_agent.domain.money import Currency, Money
from support_agent.domain.orders import OrderLine
from support_agent.domain.refunds import RefundRecord, RefundState

KEY_SEPARATOR = "|"


def _issued(records: Sequence[RefundRecord]) -> list[RefundRecord]:
    return [record for record in records if record.state is RefundState.ISSUED]


def refunded_quantity(item_id: ItemId, records: Sequence[RefundRecord]) -> int:
    return sum(record.quantity for record in _issued(records) if record.item_id == item_id)


def refundable_quantity(line: OrderLine, records: Sequence[RefundRecord]) -> int:
    return max(0, line.quantity - refunded_quantity(line.item_id, records))


def refund_amount(line: OrderLine, quantity: int) -> Money:
    return line.unit_price.times(quantity)


def refunded_total(records: Sequence[RefundRecord], currency: Currency) -> Money:
    total = Money.zero(currency)
    for record in _issued(records):
        total = total + record.amount
    return total


def idempotency_key(
    customer_id: CustomerId, order_id: OrderId, item_id: ItemId, quantity: int, already_refunded: int
) -> IdempotencyKey:
    parts = KEY_SEPARATOR.join([customer_id, order_id, item_id, str(quantity), str(already_refunded)])
    return IdempotencyKey(hashlib.sha256(parts.encode("utf-8")).hexdigest())
EOF
cat > src/support_agent/policy/rules.py <<'EOF'
"""Refund policy rules in table order (design section 4). Each returns None when it passes."""

from collections.abc import Callable
from dataclasses import dataclass

from support_agent.domain.decisions import Decision, DecisionKind, ReasonCode
from support_agent.domain.ids import ItemId
from support_agent.domain.money import Money
from support_agent.domain.orders import Order, OrderLine
from support_agent.domain.refunds import RefundRecord
from support_agent.policy.config import PolicyConfig
from support_agent.policy.refund_amounts import (
    refund_amount,
    refundable_quantity,
    refunded_total,
)

MIN_QUANTITY = 1


@dataclass(frozen=True)
class RefundCheck:
    order: Order | None
    item_id: ItemId
    quantity: int
    claimed_amounts: tuple[Money, ...]
    order_refunds: tuple[RefundRecord, ...]
    customer_refunds: tuple[RefundRecord, ...]


Rule = Callable[[RefundCheck, PolicyConfig], Decision | None]


def _deny(reason: ReasonCode) -> Decision:
    return Decision(DecisionKind.DENY, reason)


def _line(check: RefundCheck) -> tuple[Order, OrderLine] | None:
    if check.order is None:
        return None
    line = check.order.line(check.item_id)
    return None if line is None else (check.order, line)


def order_in_scope(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    return _deny(ReasonCode.ORDER_NOT_FOUND) if check.order is None else None


def order_status_eligible(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    if check.order is not None and check.order.status not in config.refundable_statuses:
        return _deny(ReasonCode.ORDER_NOT_ELIGIBLE)
    return None


def item_on_order(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    if check.order is not None and check.order.line(check.item_id) is None:
        return _deny(ReasonCode.ITEM_NOT_ON_ORDER)
    return None


def something_left_to_refund(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = _line(check)
    if resolved is not None and refundable_quantity(resolved[1], check.order_refunds) == 0:
        return _deny(ReasonCode.ALREADY_REFUNDED)
    return None


def quantity_within_refundable(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = _line(check)
    if resolved is None:
        return None
    if check.quantity < MIN_QUANTITY or check.quantity > refundable_quantity(resolved[1], check.order_refunds):
        return _deny(ReasonCode.QUANTITY_EXCEEDS_REFUNDABLE)
    return None


def order_cap(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = _line(check)
    if resolved is None:
        return None
    order, line = resolved
    already = refunded_total(check.order_refunds, order.total.currency)
    if already + refund_amount(line, check.quantity) > order.total:
        return _deny(ReasonCode.EXCEEDS_AMOUNT_PAID)
    return None


def approval_threshold(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = _line(check)
    if resolved is None:
        return None
    amount = refund_amount(resolved[1], check.quantity)
    if amount > config.approval_threshold:
        return Decision(DecisionKind.ESCALATE, ReasonCode.ABOVE_APPROVAL_THRESHOLD, amount)
    return None


def customer_cap(check: RefundCheck, config: PolicyConfig) -> Decision | None:
    resolved = _line(check)
    if resolved is None:
        return None
    amount = refund_amount(resolved[1], check.quantity)
    already = refunded_total(check.customer_refunds, amount.currency)
    if already + amount > config.customer_auto_refund_cap:
        return Decision(DecisionKind.ESCALATE, ReasonCode.CUSTOMER_LIMIT_EXCEEDED, amount)
    return None


RULES: tuple[Rule, ...] = (
    order_in_scope,
    order_status_eligible,
    item_on_order,
    something_left_to_refund,
    quantity_within_refundable,
    order_cap,
    approval_threshold,
    customer_cap,
)


def amount_dispute(check: RefundCheck, computed: Money) -> Decision | None:
    if any(claimed > computed for claimed in check.claimed_amounts):
        return Decision(DecisionKind.ESCALATE, ReasonCode.AMOUNT_DISPUTE, computed)
    return None
EOF
cat > src/support_agent/policy/engine.py <<'EOF'
"""Runs the refund rules in order; the first failing rule decides."""

from dataclasses import dataclass

from support_agent.domain.decisions import Decision, DecisionKind, ReasonCode
from support_agent.policy.config import PolicyConfig
from support_agent.policy.refund_amounts import refund_amount
from support_agent.policy.rules import RULES, RefundCheck, amount_dispute

COMPUTED_AMOUNT_KINDS = frozenset({DecisionKind.NEEDS_CONFIRMATION, DecisionKind.ESCALATE})


@dataclass(frozen=True)
class RefundAssessment:
    decision: Decision
    dispute: Decision | None


class PolicyEngine:
    def __init__(self, config: PolicyConfig) -> None:
        self._config = config

    @property
    def config(self) -> PolicyConfig:
        return self._config

    def assess_refund(self, check: RefundCheck) -> RefundAssessment:
        decision = self._decide(check)
        dispute = None
        if decision.kind in COMPUTED_AMOUNT_KINDS and decision.amount is not None:
            dispute = amount_dispute(check, decision.amount)
        return RefundAssessment(decision=decision, dispute=dispute)

    def _decide(self, check: RefundCheck) -> Decision:
        for rule in RULES:
            failure = rule(check, self._config)
            if failure is not None:
                return failure
        return self._confirmation(check)

    @staticmethod
    def _confirmation(check: RefundCheck) -> Decision:
        assert check.order is not None  # noqa: S101 - rule 1 guarantees the order
        line = check.order.line(check.item_id)
        assert line is not None  # noqa: S101 - rule 3 guarantees the line
        amount = refund_amount(line, check.quantity)
        return Decision(DecisionKind.NEEDS_CONFIRMATION, ReasonCode.CONFIRMATION_REQUIRED, amount)
EOF

