    resolved = _line(check)
    if resolved is None:
        return None
    order, line = resolved
    already = refunded_total(check.order_refunds, order.total.currency)
    if already + refund_amount(line, check.quantity) > order.total:
        return _deny(ReasonCode.EXCEEDS_AMOUNT_PAID)
    return None


