"""Refund policy configuration: pure parsing and validation, no I/O."""

from collections.abc import Mapping
from dataclasses import dataclass

from support_agent.domain.money import Currency, Money
from support_agent.domain.orders import OrderStatus

KEY_VERSION = "version"
KEY_CURRENCY = "currency"
KEY_APPROVAL_THRESHOLD = "approval_threshold"
KEY_CUSTOMER_CAP = "customer_auto_refund_cap"
KEY_REFUNDABLE_STATUSES = "refundable_statuses"


@dataclass(frozen=True)
class PolicyConfig:
    version: str
    approval_threshold: Money
    customer_auto_refund_cap: Money
    refundable_statuses: frozenset[OrderStatus]


def _required(raw: Mapping[str, object], key: str) -> object:
    if key not in raw:
        raise ValueError(f"policy config is missing '{key}'")
    return raw[key]


def _text(raw: Mapping[str, object], key: str) -> str:
    value = _required(raw, key)
    if not isinstance(value, str) or not value:
        raise ValueError(f"policy config '{key}' must be a non-empty string")
    return value


def _currency(raw: Mapping[str, object]) -> Currency:
    value = _text(raw, KEY_CURRENCY)
    try:
        return Currency(value)
    except ValueError:
        raise ValueError(f"policy config has unsupported currency '{value}'") from None


def _money(raw: Mapping[str, object], key: str, currency: Currency) -> Money:
    value = _text(raw, key)
    try:
        money = Money.parse(value, currency)
    except ArithmeticError:
        raise ValueError(f"policy config '{key}' is not a valid amount: '{value}'") from None
    if money < Money.zero(currency):
        raise ValueError(f"policy config '{key}' must be a non-negative amount")
    return money


def _statuses(raw: Mapping[str, object]) -> frozenset[OrderStatus]:
    value = _required(raw, KEY_REFUNDABLE_STATUSES)
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ValueError(f"policy config '{KEY_REFUNDABLE_STATUSES}' must be a list of strings")
    try:
        return frozenset(OrderStatus(item) for item in value)
    except ValueError as error:
        raise ValueError(f"policy config has an unknown order status: {error}") from None


def policy_config_from_mapping(raw: Mapping[str, object]) -> PolicyConfig:
    currency = _currency(raw)
    return PolicyConfig(
        version=_text(raw, KEY_VERSION),
        approval_threshold=_money(raw, KEY_APPROVAL_THRESHOLD, currency),
        customer_auto_refund_cap=_money(raw, KEY_CUSTOMER_CAP, currency),
        refundable_statuses=_statuses(raw),
    )

